-- qr_092: root ids shifted by one place after a fused word (بَعْدَمَا takes one word_index, the root ids did not)
-- in 2:181, 8:6, 13:37 (found by the qr_091 audit). Corpus check 2026-10-07: of 50,293 words with a root and a root
-- id, only 2 disagree (2:181:12 سَمِيع carried اله, 2:181:13 عَلِيم carried سمع); 10 particles carried a leftover root id.
-- Both root_uid and gid_root are fixed; each change is logged. lemma_ref (legacy, read only by old views) is NOT touched.
CREATE TABLE IF NOT EXISTS qr_word_root_link_fix (surah INTEGER NOT NULL, ayah INTEGER NOT NULL, word_index INTEGER NOT NULL,
  old_root_uid TEXT, new_root_uid TEXT, reason TEXT NOT NULL, fixed_at TEXT NOT NULL DEFAULT (datetime('now')), UNIQUE (surah, ayah, word_index));
INSERT OR IGNORE INTO qr_word_root_link_fix (surah, ayah, word_index, old_root_uid, new_root_uid, reason) SELECT 2, 181, 12, root_uid, '65a45fd3af32087f182d05201c', 'wrong root: سَمِيع carried اله' FROM qr_word_occurrence WHERE surah = 2 AND ayah = 181 AND word_index = 12 AND root_uid = 'c253f01a56574c34c66dae20de';
UPDATE qr_word_occurrence SET root_uid = '65a45fd3af32087f182d05201c', gid_root = 'AL:65a45fd3af32087f182d05201c' WHERE surah = 2 AND ayah = 181 AND word_index = 12 AND root_uid = 'c253f01a56574c34c66dae20de';
INSERT OR IGNORE INTO qr_word_root_link_fix (surah, ayah, word_index, old_root_uid, new_root_uid, reason) SELECT 2, 181, 13, root_uid, '41fedee8306a60391d0bc09327', 'wrong root: عَلِيم carried سمع' FROM qr_word_occurrence WHERE surah = 2 AND ayah = 181 AND word_index = 13 AND root_uid = '65a45fd3af32087f182d05201c';
UPDATE qr_word_occurrence SET root_uid = '41fedee8306a60391d0bc09327', gid_root = 'AL:41fedee8306a60391d0bc09327' WHERE surah = 2 AND ayah = 181 AND word_index = 13 AND root_uid = '65a45fd3af32087f182d05201c';
INSERT OR IGNORE INTO qr_word_root_link_fix (surah, ayah, word_index, old_root_uid, new_root_uid, reason) SELECT 8, 6, 10, root_uid, NULL, 'particle with no root carried a shifted root id' FROM qr_word_occurrence WHERE surah = 8 AND ayah = 6 AND word_index = 10 AND root_uid = '90b85fe773efb94f441e7263f3';
UPDATE qr_word_occurrence SET root_uid = NULL, gid_root = NULL WHERE surah = 8 AND ayah = 6 AND word_index = 10 AND root_uid = '90b85fe773efb94f441e7263f3';
